insert into public.site_content (key, data) values ('content', $serdaros_seed${"tr":{"owner":{"name":"Serdar Kerez","shortName":"Serdar","os":"SerdarOS 96","edition":"Personal Edition","tagline":"Bilgisayar Programcılığı öğrencisi · Veri Mühendisliği yolunda","location":"Antalya / Trabzon, Türkiye","email":"serdarkerez.61@gmail.com","github":"https://github.com/SerdarKerez","instagram":"https://www.instagram.com/mr.noggersengor","linkedin":"","photo":"/vesikalik.jpg","wallpaper":"/wallpaper.jpg"},"desktopIcons":["computer","projects","about","recycle","calculator","photos","mail","games","notes","welcome"],"startMenu":["notes","help","computer","games","calculator","photos","mail","profile","restart"],"files":{"about":{"title":"Hakkımda.txt","text":"Merhaba, ben Serdar Kerez.\n\nAkdeniz Üniversitesi'nde Bilgisayar Programcılığı (ön lisans) okuyorum.\nHedefim Veri Mühendisliği alanında uzmanlaşmak: veriyi toplamak,\ntemizlemek, taşımak ve anlamlı hale getirmek.\n\n--- Diller ---\nPython, C#, Delphi (Object Pascal), JavaScript, SQL (MSSQL)\n\n--- Araçlar ---\nVS Code, PyCharm, Delphi 7, SSMS, Photoshop, Adobe Animate\n\n--- Üretken AI & medya ---\nUGC reklamlar, sentetik karakterler ve enstrümantal ses üretiyorum.\nMagnific AI, Freepik AI, Seedance, Kling kullanıyor; kurguyu CapCut'ta yapıyorum.\n\n--- Boş zaman ---\nElektro gitar çalıyorum (D Standard). Metallica, Gojira, Pantera, Rammstein,\n2L8, Fairuz, Erkan Oğur, Eric Clapton dinliyorum.\nBilimkurgu, distopya ve çizgi roman okuyorum: Watchmen, Vakıf,\nDoktor Moreau'nun Adası, C. M. Kösemen.\n\nSerdarOS 96'ya hoş geldin. Etrafı kurcalamaktan çekinme!"},"welcome":{"title":"Hoş Geldin.txt","text":"SerdarOS 96 — Personal Edition\n\nBu site, kişisel portfolyomun 90'lar sonu bir masaüstü işletim sistemi\nolarak hayal edilmiş hali.\n\nNasıl kullanılır:\n • Masaüstü ikonlarına çift tıkla.\n • Pencereleri başlık çubuğundan sürükle, köşelerinden boyutlandır.\n • Sol alttaki \"start\" menüsünü keşfet.\n • Masaüstüne sağ tıkla.\n • Games klasöründe birkaç küçük oyun var.\n • Blog ikonunda yazılarımı okuyabilirsin.\n\nİyi eğlenceler!  — Serdar"},"copyright":{"title":"Telif Hakkı.txt","text":"© 2026 Serdar Kerez. Tüm hakları saklıdır.\nSerdarOS 96 hayali bir işletim sistemidir."},"privacy":{"title":"Gizlilik.txt","text":"Bu site çerez kullanmaz. Notların ve ayarların yalnızca tarayıcının localStorage alanında tutulur."}},"projects":[{"slug":"anket-portali","name":"Anket Portalı","icon":"folder","desc":"Çevrimiçi anket oluşturma ve yanıt toplama portalı.","tech":"C# · ASP.NET · MSSQL","link":""},{"slug":"genomik-crm","name":"Genomik CRM","icon":"folder","desc":"Ham DNA verisi analizi yapan genomik CRM platformu konsepti.","tech":"Python · SQL · Parquet","link":""},{"slug":"veri-bilimi","name":"Veri Bilimi Projeleri","icon":"folder","desc":"Sistem Analizi ve Tasarımı I dersi kapsamında GitHub'daki veri bilimi çalışmaları.","tech":"Python · NumPy · pandas · Seaborn","link":"https://github.com/SerdarKerez/turkcell-veri-bilimi"}],"folders":{"computer":{"title":"Bilgisayarım","items":["projects","notes","games","welcome","about","copyright","privacy","calculator","photos","mail","recycle"]},"games":{"title":"Oyunlar","items":["snake","mines","stack"]},"recycle":{"title":"Geri Dönüşüm Kutusu","items":[],"empty":"Geri dönüşüm kutusu boş."}},"photos":[{"src":"/gallery/budapest.jpg","caption":"Budapeşte'den manzara"},{"src":"/gallery/kilise.jpg","caption":"Barok bir kilisenin içi"},{"src":"/gallery/spor-salonu.jpg","caption":"Antrenman sonrası"},{"src":"/gallery/arkadaslar-1.jpg","caption":"Arkadaşlarla"},{"src":"/gallery/arkadaslar-2.jpg","caption":"Yolda, arabada"},{"src":"/gallery/kirpi.jpg","caption":"Yapraklı kirpi"}],"avatars":["guitar","cat","robot","skull","planet","dna"]},"en":{"owner":{"name":"Serdar Kerez","shortName":"Serdar","os":"SerdarOS 96","edition":"Personal Edition","tagline":"Computer Programming student · on the road to Data Engineering","location":"Antalya / Trabzon, Türkiye","email":"serdarkerez.61@gmail.com","github":"https://github.com/SerdarKerez","instagram":"https://www.instagram.com/mr.noggersengor","linkedin":"","photo":"/vesikalik.jpg","wallpaper":"/wallpaper.jpg"},"desktopIcons":["computer","projects","about","recycle","calculator","photos","mail","games","notes","welcome"],"startMenu":["notes","help","computer","games","calculator","photos","mail","profile","restart"],"files":{"about":{"title":"About Me.txt","text":"Hi, I'm Serdar Kerez.\n\nI study Computer Programming (associate degree) at Akdeniz University.\nMy goal is to specialize in Data Engineering: collecting data,\ncleaning it, moving it around and turning it into something meaningful.\n\n--- Languages ---\nPython, C#, Delphi (Object Pascal), JavaScript, SQL (MSSQL)\n\n--- Tools ---\nVS Code, PyCharm, Delphi 7, SSMS, Photoshop, Adobe Animate\n\n--- Generative AI & media ---\nI produce UGC ads, synthetic characters and instrumental audio.\nI use Magnific AI, Freepik AI, Seedance and Kling, and edit in CapCut.\n\n--- Free time ---\nI play electric guitar (D Standard). I listen to Metallica, Gojira, Pantera,\nRammstein, 2L8, Fairuz, Erkan Oğur and Eric Clapton.\nI read sci-fi, dystopias and comics: Watchmen, Foundation,\nThe Island of Doctor Moreau, C. M. Kösemen.\n\nWelcome to SerdarOS 96. Feel free to poke around!"},"welcome":{"title":"Welcome.txt","text":"SerdarOS 96 — Personal Edition\n\nThis site is my personal portfolio, reimagined as a late-'90s\ndesktop operating system.\n\nHow to use it:\n • Double-click the desktop icons.\n • Drag windows by their title bar, resize them from the corners.\n • Explore the \"start\" menu in the bottom-left corner.\n • Right-click the desktop.\n • The Games folder has a few small games.\n • Open the Blog icon to read my posts.\n\nHave fun!  — Serdar"},"copyright":{"title":"Copyright.txt","text":"© 2026 Serdar Kerez. All rights reserved.\nSerdarOS 96 is an imaginary operating system."},"privacy":{"title":"Privacy.txt","text":"This site uses no cookies. Your notes and settings are stored only in your browser's localStorage."}},"projects":[{"slug":"anket-portali","name":"Survey Portal","icon":"folder","desc":"An online portal for building surveys and collecting responses.","tech":"C# · ASP.NET · MSSQL","link":""},{"slug":"genomik-crm","name":"Genomic CRM","icon":"folder","desc":"Concept for a genomic CRM platform that analyzes raw DNA data.","tech":"Python · SQL · Parquet","link":""},{"slug":"veri-bilimi","name":"Data Science Projects","icon":"folder","desc":"Data science work on GitHub from the Systems Analysis and Design I course.","tech":"Python · NumPy · pandas · Seaborn","link":"https://github.com/SerdarKerez/turkcell-veri-bilimi"}],"folders":{"computer":{"title":"My Computer","items":["projects","notes","games","welcome","about","copyright","privacy","calculator","photos","mail","recycle"]},"games":{"title":"Games","items":["snake","mines","stack"]},"recycle":{"title":"Recycle Bin","items":[],"empty":"The Recycle Bin is empty."}},"photos":[{"src":"/gallery/budapest.jpg","caption":"A view of Budapest"},{"src":"/gallery/kilise.jpg","caption":"Inside a Baroque church"},{"src":"/gallery/spor-salonu.jpg","caption":"After a workout"},{"src":"/gallery/arkadaslar-1.jpg","caption":"With friends"},{"src":"/gallery/arkadaslar-2.jpg","caption":"On the road, in the car"},{"src":"/gallery/kirpi.jpg","caption":"Hedgehog in the leaves"}],"avatars":["guitar","cat","robot","skull","planet","dna"]}}$serdaros_seed$::jsonb)
